query notificationIntegrationWebhookList ( $accountId:ID!) {
	notification ( accountId:$accountId ) {
		integration {
			webhookList {
				items {
					id
					name
					enabled
					url
					requestMethod
					auth {
						authType
						... on BasicAuth {
							username
						}
						... on CustomHeaderAuth {
							name
						}
						... on CustomHeadersAuth {
							plainHeaders {
								name
								value
							}
							secretHeaders {
								name
							}
						}
					}
					header {
						name
						value
					}
					body
					responseMapping {
						key
						value
					}
					relatedWebhookId
				}
				paging {
					total
				}
			}
		}
	}	
}
